fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let base: i32 = h - 8;
    let life: i32 = 64;
    host::display::clear(0x000000);
    host::display::fill_rect(cx - 6, base, 12, 8, 0x404040);
    let mut i: i32 = 0;
    while i < 40 {
        let age: i32 = (t + hash(i * 3 + 1) % life) % life;
        let vx: i32 = hash(i * 7 + 2) % 7 - 3;
        let vy: i32 = hash(i * 11 + 5) % 4 + 5;
        let x: i32 = cx + vx * age / 2;
        let y: i32 = base - vy * age + age * age / 8;
        let c: i32 = if age < 20 { 0xffff80 } else if age < 44 { 0xff9020 } else { 0x802010 };
        if y < base {
            host::display::fill_rect(x, y, 3, 3, c);
        }
        i = i + 1;
    }
    host::display::present();
}
